draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // Draw a balance scale
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2, H/2 - 100);
  ctx.stroke();

  // Draw the left plate
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2 - 50, 50, 0, 2 * Math.PI);
  ctx.stroke();

  // Draw the right plate
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2 - 50, 50, 0, 2 * Math.PI);
  ctx.stroke();

  // Draw a figure on the left plate
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2 - 50 + 20 + 20 * Math.sin(t), 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 - 50 + 30 + 20 * Math.sin(t));
  ctx.lineTo(W/2 - 50, H/2 - 50 + 60 + 20 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 - 50 + 45 + 20 * Math.sin(t));
  ctx.lineTo(W/2 - 70, H/2 - 50 + 60 + 20 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 - 50 + 45 + 20 * Math.sin(t));
  ctx.lineTo(W/2 - 30, H/2 - 50 + 60 + 20 * Math.sin(t));
  ctx.stroke();

  // Draw a figure on the right plate
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2 - 50 + 20 - 20 * Math.sin(t), 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 - 50 + 30 - 20 * Math.sin(t));
  ctx.lineTo(W/2 + 50, H/2 - 50 + 60 - 20 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 - 50 + 45 - 20 * Math.sin(t));
  ctx.lineTo(W/2 + 30, H/2 - 50 + 60 - 20 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 - 50 + 45 - 20 * Math.sin(t));
  ctx.lineTo(W/2 + 70, H/2 - 50 + 60 - 20 * Math.sin(t));
  ctx.stroke();

  ctx.restore();
}
